 Ünker","role":"","company":"","avatar":"","quote":"Satışı, insanı anlamak ve doğru soruları sormak üzerinden ele alan bir yaklaşım.","status":"draft","enabled":true,"approvedAt":""},{"id":"nilay-birdal","name":"Nilay Birdal","role":"","company":"","avatar":"","quote":"İlham veren fikirleri, üzerinde çalışılabilecek somut adımlarla buluşturuyor.","status":"draft","enabled":true,"approvedAt":""}]}}$zsy_book_ref$::jsonb,revision=revision+1,published_revision=revision+1,updated_at=now() where id='/';
insert into public.cms_published(id,route,kind,payload,revision,published_at) select id,route,kind,draft,revision,now() from public.cms_documents where id='/' on conflict(id) do update set payload=excluded.payload,revision=excluded.revision,published_at=excluded.published_at;
