do $guard$ begin if not exists(select 1 from public.cms_documents d join public.cms_published p using(id) where d.id='/kitaplar/' and d.revision=2 and d.draft=$zsy_book_ref${"id":"/kitaplar/","kind":"page","route":"/kitaplar/","title":"Ziya Şakir Yılmaz’ın Kitapları | Başarı ve Kafa Yapısı","values":{"96c86e3b-85:@src":"/assets/hero-loop-restored-1440.mp4","96c86e3b-87:text":"Ziya Şakir Yılmaz","96c86e3b-88:text":"Kitaplar","96c86e3b-89:text":"Bir fikir,","96c86e3b-90:tail":"sayfalar boyunca.","96c86e3b-91:text":"Başarı, dönüşüm ve zihinsel dayanıklılık üzerine Ziya Şakir Yılmaz’ın kitapları.","96c86e3b-95:text":"Videoyu duraklat","96c86e3b-101:text":"Düşünceden sayfaya","96c86e3b-102:text":"Okumakla başlayan yolculuk.","96c86e3b-106:@alt":"Ziya Şakir Yılmaz — Kurşun Geçirmez Kafa Yapısı kitap kapağı","96c86e3b-106:@src":"/assets/kapak-kursun-mockup.webp","96c86e3b-108:text":"EKİM 2026 · YENİ · İMZA SİSTEMİN KİTABI","96c86e3b-109:text":"Kurşun Geçirmez Kafa Yapısı","96c86e3b-110:text":"İçindeki Sabotajcı’yı fark etmek; HENÜZ, RAĞMEN ve MÜMKÜN diliyle düşünmek; zor anlarda durmak ve yeniden seçmek. Kitabın sayfasında: ücretsiz öz değerlendirme testi ve 66 Günlük Oyun Planı.","96c86e3b-112:text":"Kitabı keşfet","96c86e3b-117:@alt":"Başarı Mühendisliği kitap kapağı","96c86e3b-117:@src":"/assets/kapak-bm.webp","96c86e3b-119:text":"2020 · 5. BASKI","96c86e3b-120:text":"Başarı Mühendisliği","96c86e3b-121:text":"Başarıyı şanstan sisteme çeviren yaklaşımın temel kitabı: Ben Yasası, Sitem / Sistem, Başarı Ceketinin Üç Düğmesi, Kadar / Keder ve Üç Filtre.","96c86e3b-123:text":"Kitapyurdu'nda Gör","96c86e3b-128:@alt":"Size Bir Sır Vereyim mi? kitap kapağı","96c86e3b-128:@src":"/assets/kapak-sir.webp","96c86e3b-130:text":"2016","96c86e3b-131:text":"Size Bir Sır Vereyim mi?","96c86e3b-132:text":"Yolculuğun başladığı yer: dönüşümün ilk anahtarları.","96c86e3b-134:text":"Kitapyurdu'nda Gör","96c86e3b-139:@alt":"İlk 72 Saat kitap kapağı","96c86e3b-139:@src":"/assets/kapak-72.webp",