86e3b-143:text":"Yeni nesil e-ticaret ekiplerine doğru başlamanın el kitabı: bir işe başlayan kişinin ilk üç gününün sistemi.","96c86e3b-145:text":"Kitapyurdu'nda Gör","96c86e3b-150:text":"Kitapların fikir zinciri","96c86e3b-154:text":"Kitaplar bir katalog gibi yan yana durmaz; bir düşünce sisteminin zaman içindeki halkalarıdır. Her halkanın altında fikir, araç, içerik ve eğitim bağlantısı var.","96c86e3b-158:text":"Yıl","96c86e3b-159:text":"Kitap","96c86e3b-160:text":"Fikir","96c86e3b-161:text":"Araç","96c86e3b-162:text":"İçerik","96c86e3b-163:text":"Eğitim","96c86e3b-166:text":"İlk kitap","96c86e3b-168:tail":" (Emre Topçu ile)","96c86e3b-168:text":"İlk 72 Saat","96c86e3b-169:text":"Bir işin ilk üç günü kalıcılığı belirler","96c86e3b-171:text":"Sistemli yol haritası","96c86e3b-173:text":"Satış Rehberi","96c86e3b-175:text":"Satış programı","96c86e3b-177:text":"2016","96c86e3b-179:text":"Size Bir Sır Vereyim mi?","96c86e3b-180:text":"Dönüşümün ilk anahtarları","96c86e3b-182:text":"Kafa Yapısı Skoru","96c86e3b-184:text":"Başarı Rehberi","96c86e3b-186:text":"Bireysel programlar","96c86e3b-188:text":"2020","96c86e3b-190:text":"Başarı Mühendisliği","96c86e3b-191:text":"Başarı tesadüfün konusu olmaktan çıkar, tasarlanır","96c86e3b-193:text":"Ekip değerlendirmesini görüşelim","96c86e3b-195:text":"İmza sistem","96c86e3b-197:text":"Liderlik programı","96c86e3b-200:text":"Ekim 2026","96c86e3b-202:text":"Kurşun Geçirmez Kafa Yapısı","96c86e3b-203:text":"İnsan sakin kaldığı her şeyin galibidir","96c86e3b-205:tail":" · ","96c86e3b-205:text":"KGKY Skoru","96c86e3b-206:text":"66 Günlük Oyun Planı","96c86e3b-208:text":"Kafa Yapısı Rehberi","96c86e3b-210:text":"KGKY Atölyesi","96c86e3b-215:text":"Kurşun Geçirmez Kafa Yapısı","96c86e3b-216:text":"Hayatın içinde","96c86e3b-217:tail":"sağlam kalmak.","96c86e3b-218:text":"Sabotajcı, HENÜZ–RAĞMEN–MÜMKÜN, 90 saniye ve HAYIR kavramlarıyla zihinsel dayanıklılık üzerine yaklaşımı tanıyın.","96c86e3b-220:text":"Kurşun Geçirmez Kafa Yapısı’nı keşfet","96c86e3b-85:focal":"center center","96c86e3b-87:@href":"/","96c86e3b-106:focal":"center center","96c86e3b-111:@href":"/kursun-gecirmez-kafa-yapisi/","96c86e3b-117:focal":"center center","96c86e3b-122:@href":"https://www.kitapyurdu.com/kitap/basari-muhendisligi/564766.html","96c86e3b-128:focal":"center center","96c86e3b-133:@href":"https://www.kitapyurdu.com/yazar/ziya-sakir-yilmaz/203025.html","96c86e3b-139:focal":"center center","96c86e3b-144:@href":"https://www.kitapyurdu.com/yazar/ziya-sakir-yilmaz/203025.html","96c86e3b-171:@href":"/makaleler/nasil-basarili-olunur/","96c86e3b-173:@href":"/satis/","96c86e3b-175:@href":"/kurumsal/satis-egitimi/","96c86e3b-182:@href":"/testler/kafa-yapisi-testi/","96c86e3b-184:@href":"/basari/","96c86e3b-186:@href":"/egitimler/","96c86e3b-193:@href":"/iletisim/?konu=kurumsal#talep-formu","96c86e3b-195:@href":"/basari-muhendisligi/","96c86e3b-197:@href":"/kurumsal/liderlik-egitimi/","96c86e3b-205:@href":"/testler/kafa-yapisi-testi/","96c86e3b-206:@href":"/kursun-gecirmez-kafa-yapisi/#oyun-plani","96c86e3b-208:@href":"/kafa-yapisi/","96c86e3b-210:@href":"/kurumsal/kafa-yapisi-atolyesi/","96c86e3b-219:@href":"/kursun-gecirmez-kafa-yapisi/","96c86e3b-85:@poster":"/assets/hero-restored-poster.jpg","96c86e3b-85:@data-start-at":"7.3"},"ogImage":"/assets/og/kitaplar.png","sections":[{"id":"96c86e3b-83","groups":[],"hidden":false,"source":"96c86e3b-83","values":{}},{"id":"96c86e3b-96","groups":[{"id":"96c86e3b-103","items":[{"id":"96c86e3b-104","source":"96c86e3b-104","values":{}},{"id":"96c86e3b-115","source":"96c86e3b-115","values":{}},{"id":"96c86e3b-126","source":"96c86e3b-126","values":{}},{"id":"96c86e3b-137","source":"96c86e3b-137","values":{}}]},{"id":"96c86e3b-164","items":[{"id":"96c86e3b-165","source":"96c86e3b-165","values":{}},{"id":"96c86e3b-176","source":"96c86e3b-176","values":{}},{"id":"96c86e3b-187","source":"96c86e3b-187","values":{}},{"id":"96c86e3b-198","source":"96c86e3b-198","values":{}}]}],"hidden":false,"source":"96c86e3b-96","values":{}},{"id":"96c86e3b-211","groups":[],"hidden":false,"source":"96c86e3b-211","values":{}}],"template":"/kitaplar/","ogImageAlt":"Bir fikir, sayfalar boyunca. — Ziya Şakir Yılmaz adını içeren paylaşım görseli.","description":"Kurşun Geçirmez Kafa Yapısı, Başarı Mühendisliği, Size Bir Sır Vereyim mi? ve İlk 72 Saat. Ziya Şakir Yılmaz’ın dört kitabını ve konularını keşfedin.","ogImageAltFor":"/assets/og/kitaplar.png"}$zsy_book_ref$::jsonb,revision=revision+1,published_revision=revision+1,updated_at=now() where id='/kitaplar/';
insert into public.cms_published(id,route,kind,payload,revision,published_at) select id,route,kind,draft,revision,now() from public.cms_documents where id='/kitaplar/' on conflict(id) do update set payload=excluded.payload,revision=excluded.revision,published_at=excluded.published_at;
insert into public.cms_versions(document_id,payload,revision,action) select id,draft,revision,'publish' from public.cms_documents where id='/kitaplar/';
do $guard$ begin if not exists(select 1 from public.cms_documents d join public.cms_published p using(id) where d.id='/basari-muhendisligi/' and d.revision=2 and d.draft=$zsy_book_ref${"id":"/basari-muhendisligi/","kind":"page","route":"/basari-muhendisligi/","title":"Başarı Mühendisliği: 5 Aşamalı Yaklaşım | Ziya Şakir Yılmaz","values":{"eea7dbba-84:@src":"/assets/hero-loop-restored-1440.mp4","eea7dbba-86:text":"Ziya Şakir Yılmaz","eea7dbba-87:text":"Ziya Şakir Yılmaz’ın yaklaşımı","eea7dbba-88:text":"Başarı Mühendisliği™","eea7dbba-89:text":"Hedefi, günlük eylemi ve gelişimi aynı sistemde buluşturmak.","eea7dbba-93:text":"Videoyu duraklat","eea7dbba-102:text":"Mühendislik bakışı","eea7dbba-104:text":"Bir hedef,","eea7dbba-105:tail":"nasıl çalışan bir","eea7dbba-106:tail":"sisteme dönüşür?","eea7dbba-107:text":"Başarı Mühendisliği, başarıyı ilham ve şansla sınırlamadan; hedef, alışkanlık ve ölçüm üzerine kurulabilen bir süreç olarak ele alır. Yaklaşımın ilkeleri kitapta, uygulaması eğitimlerde hayat bulur.","eea7dbba-110:text":"Mühendis gözüyle başarı","eea7dbba-115:text":"30 Saniyede Cevap","eea7dbba-116:tail":", başarıyı ilham ve şans konusu olmaktan çıkarıp ","eea7dbba-116:text":"Başarı Mühendisliği™","eea7dbba-117:tail":" üzerine kurulan tasarlanabilir bir sürece dönüştüren yaklaşımdır. Kavram ","eea7dbba-117:text":"hedef, sistem, alışkanlık ve ölçüm","eea7dbba-118:tail":" tarafından geliştirilmiş ve 2020 tarihli aynı adlı kitapta ortaya konmuştur. Sistem iki katmanda yaşar: kitaptaki ilkeler ve eğitim salonundaki beş aşamalı uygulama modeli (","eea7dbba-118:text":"Ziya Şakir Yılmaz","eea7dbba-119:tail":").\n      ","eea7dbba-119:text":"Keşif, Tasarım, İnşa, Test, Bakım","eea7dbba-120:text":"Mühendis gözüyle başarı","eea7dbba-121:text":"Bir köprü umutla ayakta durmaz; hesapla durur. Başarı Mühendisliği aynı disiplini insan hedeflerine uygular: nereye varılacak (Keşif), hangi sistemle (Tasarım), hangi günlük eylemlerle (İnşa), neyle ölçülecek ve engeller nasıl aşılacak (Test), sonuç nasıl korunacak ve büyütülecek (Bakım). Motivasyon bu sistemde yakıttır; motor ise sistemin kendisidir.","eea7dbba-122:text":"Yaklaşımın üç ayırt edici ilkesi vardır. Birincisi ölçümdür: ölçülmeyen hedef, dilektir. İkincisi kanıttır: yöntemler hedef belirleme ve alışkanlık araştırmalarının bulguları üzerine kurulur. Üçüncüsü dayanıklılıktır: her sistem fırtınaya girer; bu yüzden Başarı Mühendisliği'nin zihinsel altyapı katmanı ","eea7dbba-123:tail":"'dır. Biri rotayı çizer, diğeri fırtınada rotada tutar.","eea7dbba-123:text":"Kurşun Geçirmez Kafa Yapısı™","eea7dbba-128:text":"Eğitimde uygulama","eea7dbba-129:text":"Eğitim salonundaki uygulama modeli","eea7dbba-130:text":"Aşağıdaki beş aşama kitabın bölüm yapısı değildir; Başarı Mühendisliği yaklaşımının eğitim ve uygulama sürecinde kullanılan çalışma modelidir.","eea7dbba-133:text":"01","eea7dbba-134:text":"Keşif","eea7dbba-135:text":"Neredeyim, nereye gidiyorum?","eea7dbba-137:text":"02","eea7dbba-138:text":"Tasarım","eea7dbba-139:text":"Hedef hangi sisteme dönüşecek?","eea7dbba-141:text":"03","eea7dbba-142:text":"İnşa","eea7dbba-143:text":"Günlük hangi davranışlar uygulanacak?","eea7dbba-145:text":"04","eea7dbba-146:text":"Test","eea7dbba-147:text":"Ne çalışıyor, ne çalışmıyor?","eea7dbba-149:text":"05","eea7dbba-150:text":"Bakım","eea7dbba-151:text":"Sonuç nasıl korunacak ve geliştirilecek?","eea7dbba-157:@alt":"Başarı Mühendisliği kitap kapağı","eea7dbba-157:@src":"/assets/kapak-bm.webp","eea7dbba-160:text":"Kitaptan uygulamaya","eea7dbba-161:text":"Başarı Mühendisliği","eea7dbba-162:text":"Ziya Şakir Yılmaz’ın aynı adlı kitabı; yaklaşımın ilkelerini, düşünme biçimini ve saha örneklerini bir araya getirir.","eea7dbba-164:text":"Kitapları keşfet","eea7dbba-168:text":"Eğitimlere göz at","eea7dbba-172:text":"Kitaptaki ilkeler","eea7dbba-175:text":"Ben Yasası","eea7dbba-179:text":"\"Kim olduğumuz, ne yaptığımızdır.\" Kimlik sözle kurulmaz; tekrar edilen davranışla kurulur.","eea7dbba-182:text":"Sitem / Sistem","eea7dbba-186:text":"Aynı harfler, iki ayrı hayat: şikâyet eden sitem kurar, sonuç alan sistem kurar.","eea7dbba-189:text":"Başarı Ceketinin Üç Düğmesi","eea7dbba-193:text":"Gülümsemek, paylaşmak, güvenmek. Başarı yalnız sonuçla ölçülmez; bıraktığın izle ölçülür.","eea7dbba-196:text":"Kadar / Keder","eea7dbba-200:text":"\"Kadar mısın, Keder misin?\" Kadar kapasitendir, gelişmeye açık imkândır; kabuğunu kırmayıp kadarında kalanın sınırı kedere dönüşür.","eea7dbba-203:text":"Üç Filtre","eea7dbba-207:text":"Karar ve bilgiyi üç süzgeçten geçirmek; her sese değil, doğru sese kulak vermek.","eea7dbba-212:text":"Birlikte uygulayalım","eea7dbba-213:text":"Kendi sisteminizi","eea7dbba-214:tail":"kurmaya başlayın.","eea7dbba-217:text":"Bireysel eğitim almak istiyorum","eea7dbba-84:focal":"center center","eea7dbba-86:@href":"/","eea7dbba-118:@href":"/ziya-sakir-yilmaz/","eea7dbba-123:@href":"/kursun-gecirmez-kafa-yapisi/","eea7dbba-157:focal":"center center","eea7dbba-163:@href":"/kitaplar/","eea7dbba-167:@href":"/egitimler/","eea7dbba-216:@href":"/iletisim/?konu=bireysel#talep-formu","eea7dbba-84:@poster":"/assets/hero-restored-poster.jpg","eea7dbba-84:@data-start-at":"2.2"},"ogImage":"/assets/og/basari-muhendisligi.png","sections":[{"id":"eea7dbba-82","groups":[],"hidden":false,"source":"eea7dbba-82","values":{}},{"id":"eea7dbba-94","groups":[],"hidden":false,"source":"eea7dbba-94","values":{}},{"id":"eea7dbba-124","groups":[{"id":"eea7dbba-131","items":[{"id":"eea7dbba-132","source":"eea7dbba-132","values":{}},{"id":"eea7dbba-136","source":"eea7dbba-136","values":{}},{"id":"eea7dbba-140","source":"eea7dbba-140","values":{}},{"id":"eea7dbba-144","source":"eea7dbba-144","values":{}},{"id":"eea7dbba-148","source":"eea7dbba-148","values":{}}]}],"hidden":false,"source":"eea7dbba-124","values":{}},{"id":"eea7dbba-152","groups":[{"id":"eea7dbba-154","items":[{"id":"eea7dbba-155","source":"eea7dbba-155","values":{}}]}],"hidden":false,"source":"eea7dbba-152","values":{}},{"id":"eea7dbba-208","groups":[],"hidden":false,"source":"eea7dbba-208","values":{}}],"template":"/basari-muhendisligi/","ogImageAlt":"Başarı Mühendisliği — Ziya Şakir Yılmaz adını içeren paylaşım görseli.","description":"Başarı Mühendisliği yaklaşımını tanıyın: keşif, tasarım, inşa, test ve bakım. Hedefinizi günlük eyleme dönüştüren sistemi, kitabı ve uygulama adımlarını keşfedin.","ogImageAltFor":"/assets/og/basari-muhendisligi.png"}$zsy_book_ref$::jsonb and p.revision=2 and p.payload=$zsy_book_ref${"id":"/basari-muhendisligi/","kind":"page","route":"/basari-muhendisligi/","title":"Başarı Mühendisliği: 5 Aşamalı Yaklaşım | Ziya Şakir Yılmaz","values":{"eea7dbba-84:@src":"/assets/hero-loop-restored-1440.mp4","eea7dbba-86:text":"Ziya Şakir Yılmaz","eea7dbba-87:text":"Ziya Şakir Yılmaz’ın yaklaşımı","eea7dbba-88:text":"Başarı Mühendisliği™","eea7dbba-89:text":"Hedefi, günlük eylemi ve gelişimi aynı sistemde buluşturmak.","eea7dbba-93:text":"Videoyu duraklat","eea7dbba-102:text":"Mühendislik bakışı","eea7dbba-104:text":"Bir hedef,","eea7dbba-105:tail":"nasıl çalışan bir","eea7dbba-106:tail":"sisteme dönüşür?","eea7dbba-107:text":"Başarı Mühendisliği, başarıyı ilham ve şansla sınırlamadan; hedef, alışkanlık ve ölçüm üzerine kurulabilen bir süreç olarak ele alır. Yaklaşımın ilkeleri kitapta, uygulaması eğitimlerde hayat bulur.","eea7dbba-110:text":"Mühendis gözüyle başarı","eea7dbba-115:text":"30 Saniyede Cevap","eea7dbba-116:tail":", başarıyı ilham ve şans konusu olmaktan çıkarıp ","eea7dbba-116:text":"Başarı Mühendisliği™","eea7dbba-117:tail":" üzerine kurulan tasarlanabilir bir sürece dönüştüren yaklaşımdır. Kavram ","eea7dbba-117:text":"hedef, sistem, alışkanlık ve ölçüm","eea7dbba-118:tail":" tarafından geliştirilmiş ve 2020 tarihli aynı adlı kitapta ortaya konmuştur. Sistem iki katmanda yaşar: kitaptaki ilkeler ve eğitim salonundaki beş aşamalı uygulama modeli (","eea7dbba-118:text":"Ziya Şakir Yılmaz","eea7dbba-119:tail":").\n      ","eea7dbba-119:text":"Keşif, Tasarım, İnşa, Test, Bakım","eea7dbba-120:text":"Mühendis gözüyle başarı","eea7dbba-121:text":"Bir köprü umutla ayakta durmaz; hesapla durur. Başarı Mühendisliği aynı disiplini insan hedeflerine uygular: nereye varılacak (Keşif), hangi sistemle (Tasarım), hangi günlük eylemlerle (İnşa), neyle ölçülecek ve engeller nasıl aşılacak (Test), sonuç nasıl korunacak ve büyütülecek (Bakım). Motivasyon bu sistemde yakıttır; motor ise sistemin kendisidir.","eea7dbba-122:text":"Yaklaşımın üç ayırt edici ilkesi vardır. Birincisi ölçümdür: ölçülmeyen hedef, dilektir. İkincisi kanıttır: yöntemler hedef belirleme ve alışkanlık araştırmalarının bulguları üzerine kurulur. Üçüncüsü dayanıklılıktır: her sistem fırtınaya girer; bu yüzden Başarı Mühendisliği'nin zihinsel altyapı katmanı ","eea7dbba-123:tail":"'dır. Biri rotayı çizer, diğeri fırtınada rotada tutar.","eea7dbba-123:text":"Kurşun Geçirmez Kafa Yapısı™","eea7dbba-128:text":"Eğitimde uygulama","eea7dbba-129:text":"Eğitim salonundaki uygulama modeli","eea7dbba-130:text":"Aşağıdaki beş aşama kitabın bölüm yapısı değildir; Başarı Mühendisliği yaklaşımının eğitim ve uygulama sürecinde kullanılan çalışma modelidir.","eea7dbba-133:text":"01","eea7dbba-134:text":"Keşif","eea7dbba-135:text":"Neredeyim, nereye gidiyorum?","eea7dbba-137:text":"02","eea7dbba-138:text":"Tasarım","eea7dbba-139:text":"Hedef hangi sisteme dönüşecek?","eea7dbba-141:text":"03","eea7dbba-142:text":"İnşa","eea7dbba-143:text":"Günlük hangi davranışlar uygulanacak?","eea7dbba-145:text":"04","eea7dbba-146:text":"Test","eea7dbba-147:text":"Ne çalışıyor, ne çalışmıyor?","eea7dbba-149:text":"05","eea7dbba-150:text":"Bakım","eea7dbba-151:text":"Sonuç nasıl korunacak ve geliştirilecek?","eea7dbba-157:@alt":"Başarı Mühendisliği kitap kapağı","eea7dbba-157:@src":"/assets/kapak-bm.webp","eea7dbba-160:text":"Kitaptan uygulamaya","eea7dbba-161:text":"Başarı Mühendisliği","eea7dbba-162:text":"Ziya Şakir Yılmaz’ın aynı adlı kitabı; yaklaşımın ilkelerini, düşünme biçimini ve saha örneklerini bir araya getirir.","eea7dbba-164:text":"Kitapları keşfet","eea7dbba-168:text":"Eğitimlere göz at","eea7dbba-172:text":"Kitaptaki ilkeler","eea7dbba-175:text":"Ben Yasası","eea7dbba-179:text":"\"Kim olduğumuz, ne yaptığımızdır.\" Kimlik sözle kurulmaz; tekrar edilen davranışla kurulur.","eea7dbba-182:text":"Sitem / Sistem","eea7dbba-186:text":"Aynı harfler, iki ayrı hayat: şikâyet eden sitem kurar, sonuç alan sistem kurar.","eea7dbba-189:text":"Başarı Ceketinin Üç Düğmesi","eea7dbba-193:text":"Gülümsemek, paylaşmak, güvenmek. Başarı yalnız sonuçla ölçülmez; bıraktığın izle ölçülür.","eea7dbba-196:text":"Kadar / Keder","eea7dbba-200:text":"\"Kadar mısın, Keder misin?\" Kadar kapasitendir, gelişmeye açık imkândır; kabuğunu kırmayıp kadarında kalanın sınırı kedere dönüşür.","eea7dbba-203:text":"Üç Filtre","eea7dbba-207:text":"Karar ve bilgiyi üç süzgeçten geçirmek; her sese değil, doğru sese kulak vermek.","eea7dbba-212:text":"Birlikte uygulayalım","eea7dbba-213:text":"Kendi sisteminizi","eea7dbba-214:tail":"kurmaya başlayın.","eea7dbba-217:text":"Bireysel eğitim almak istiyorum","eea7dbba-84:focal":"center center","eea7dbba-86:@href":"/","eea7dbba-118:@href":"/ziya-sakir-yilmaz/","eea7dbba-123:@href":"/kursun-gecirmez-kafa-yapisi/","eea7dbba-157:focal":"center center","eea7dbba-163:@href":"/kitaplar/","eea7dbba-167:@href":"/egitimler/","eea7dbba-216:@href":"/iletisim/?konu=bireysel#talep-formu","eea7dbba-84:@poster":"/assets/hero-restored-poster.jpg","eea7dbba-84:@data-start-at":"2.2"},"ogImage":"/assets/og/basari-muhendisligi.png","sections":[{"id":"eea7dbba-82","groups":[],"hidden":false,"source":"eea7dbba-82","values":{}},{"id":"eea7dbba-94","groups":[],"hidden":false,"source":"eea7dbba-94","values":{}},{"id":"eea7dbba-124","groups":[{"id":"eea7dbba-131","items":[{"id":"eea7dbba-132","source":"eea7dbba-132","values":{}},{"id":"eea7dbba-136","source":"eea7dbba-136","values":{}},{"id":"eea7dbba-140","source":"eea7dbba-140","values":{}},{"id":"eea7dbba-144","source":"eea7dbba-144","values":{}},{"id":"eea7dbba-148","source":"eea7dbba-148","values":{}}]}],"hidden":false,"source":"eea7dbba-124","values":{}},{"id":"eea7dbba-152","groups":[{"id":"eea7dbba-154","items":[{"id":"eea7dbba-155","source":"eea7dbba-155","values":{}}]}],"hidden":false,"source":"eea7dbba-152","values":{}},{"id":"eea7dbba-208","groups":[],"hidden":false,"source":"eea7dbba-208","values":{}}],"template":"/basari-muhendisligi/","ogImageAlt":"Başarı Mühendisliği — Ziya Şakir Yılmaz adını içeren paylaşım görseli.","description":"Başarı Mühendisliği yaklaşımını tanıyın: keşif, tasarım, inşa, test ve bakım. Hedefinizi günlük eyleme dönüştüren sistemi, kitabı ve uygulama adımlarını keşfedin.","ogImageAltFor":"/assets/og/basari-muhendisligi.png"}$zsy_book_ref$::jsonb) then raise exception 'Content changed: /basari-muhendisligi/'; end if; end $guard$;
